    static readonly Dictionary<int, Geometry> Cache = new();

    /// Null kalau job ID nggak punya ikon.
    public static Geometry? Get(int jobId)
    {
        if (Cache.TryGetValue(jobId, out var g)) return g;
        if (!Paths.TryGetValue(jobId, out var path)) return null;
        g = Geometry.Parse(path);
        g.Freeze();
        Cache[jobId] = g;
        return g;
    }
}
